query:
-- Delete core ticket and call data
DELETE FROM ticketReplies;
DELETE FROM tickets;
DELETE FROM callDraftTickets;
DELETE FROM callLogs;

-- Verify deletion
SELECT 
  (SELECT COUNT(*) FROM callLogs) as remaining_callLogs,
  (SELECT COUNT(*) FROM callDraftTickets) as remaining_drafts,
  (SELECT COUNT(*) FROM tickets) as remaining_tickets,
  (SELECT COUNT(*) FROM ticketReplies) as remaining_replies;

